import type { ViewerPluginCreator } from './../ricos-types/index.js';

import { DEFAULT_CONFIG } from './constants.js';
import type { ActionButtonPluginViewerConfig, LinkButtonPluginViewerConfig } from './types.js';
import { ACTION_BUTTON_TYPE, LINK_BUTTON_TYPE } from './types.js';
import { nodeViewRenderers } from './viewer/node-view-renderers.js';

const pluginButton = (type: $TSFixMe, config: $TSFixMe) => {
  return {
    config: { ...DEFAULT_CONFIG, ...config },
    type,
    nodeViewRenderers,
  };
};

export const pluginLinkButton: ViewerPluginCreator<LinkButtonPluginViewerConfig> = config => {
  return pluginButton(LINK_BUTTON_TYPE, config);
};

export const pluginActionButton: ViewerPluginCreator<ActionButtonPluginViewerConfig> = config => {
  return pluginButton(ACTION_BUTTON_TYPE, config);
};
