import {
  Box,
  FieldSet,
  FillPreview,
  FormField,
  Input,
  SegmentedToggle,
  Thumbnail,
} from '@wix/design-system';
import { ButtonRoundedSmall } from '@wix/wix-ui-icons-common/lazy';
import type { ReactNode } from 'react';
import React, { useContext, useEffect, useReducer, useRef, useState } from 'react';

import {
  EditorContext,
  ModalServiceContext,
  RicosContext,
  ZIndexContext,
} from './../../ricos-context/index.js';
import { ButtonData_Styles_ButtonSize } from './../../ricos-schema/next-schema/generated/ricos_document.js';
import { toHexFormat } from './../../ricos-styles/index.js';
import type { Gradient } from './../../ricos-types/color-palette-types.js';
import type { LogBiFn } from './../../_shared/bi-context-provider/bi-context-provider.js';
import type { PmActionButtonNode, PmLinkButtonNode, PmNodeType } from './../../_shared/pm-node-types.js';
import { resolveColorToDisplayHex } from './../../_shared/resolve-color-to-display-hex.js';
import { schemaGradientToCss } from './../../_shared/schema-gradient-to-css.js';
import { useNodeAttrs } from './../../_shared/use-node-attrs.js';
import { ButtonColorPicker } from './../components/button-color-picker.js';
import { buttonsModals } from './../constants.js';
import { SWATCH_TOGGLE } from './../../ui-components/color-picker/button-color-swatches/data-hooks.js';
import {
  ColorPickerLiveSiteColorHint,
  ColorWithOpacityInput,
  NumberInputWithLabel,
  usePanelContainerElement,
} from './../../ui-components/index.js';

import {
  DESIGN_SETTINGS_BACKGROUND_COLOR_INPUT,
  DESIGN_SETTINGS_BORDER_COLOR_INPUT,
  DESIGN_SETTINGS_BORDER_WIDTH_INPUT,
  DESIGN_SETTINGS_CORNER_RADIUS_INPUT,
  DESIGN_SETTINGS_TEXT_COLOR_INPUT,
} from '../data-hooks.js';
import type { ButtonPluginEditorConfigCommon } from '../types.js';

type DesignComponentProps = {
  config: ButtonPluginEditorConfigCommon;
  onChange: (data: Partial<(PmLinkButtonNode | PmActionButtonNode)['attrs']>) => void;
  defaultBackgroundColor?: string;
  defaultTextColor?: string;
  nodeId: string;
  nodeType: typeof PmNodeType.LINK_BUTTON | typeof PmNodeType.ACTION_BUTTON;
  logBi: LogBiFn;
};

const defaultBorderRadius = 0;
const defaultBorderWidth = 0;

const BUTTON_NORMAL_STATE_TOGGLE_VALUE = 'NORMAL';
const BUTTON_HOVER_STATE_TOGGLE_VALUE = 'HOVER';

type BUTTON_STATE_TOGGLE_VALUE =
  | typeof BUTTON_NORMAL_STATE_TOGGLE_VALUE
  | typeof BUTTON_HOVER_STATE_TOGGLE_VALUE;

export type ButtonColorType = 'backgroundColor' | 'textColor' | 'borderColor';

const themeButtonSizeMap = {
  small: ButtonData_Styles_ButtonSize.SMALL,
  medium: ButtonData_Styles_ButtonSize.MEDIUM,
  large: ButtonData_Styles_ButtonSize.LARGE,
};

export const DesignComponent: React.FC<DesignComponentProps> = ({
  config,
  onChange,
  defaultBackgroundColor,
  defaultTextColor,
  nodeId,
  nodeType,
  logBi,
}) => {
  const { t, isMobile, environment, theme } = useContext(RicosContext);
  const modalService = useContext(ModalServiceContext);
  const { adapter } = useContext(EditorContext);
  const { pmNodeAttrs } = useNodeAttrs(nodeId, nodeType);
  const containerEl = usePanelContainerElement();
  const forceUpdate = useReducer(x => x + 1, 0)[1];

  const zIndexService = useContext(ZIndexContext);
  const zIndex = zIndexService.getZIndex('DIALOG');

  const backgroundPickerToggleRef = useRef<HTMLDivElement>(null);
  const textPickerToggleRef = useRef<HTMLDivElement>(null);
  const borderPickerToggleRef = useRef<HTMLDivElement>(null);

  const [buttonStateToggleValue, setButtonStateToggleValue] =
    useState<BUTTON_STATE_TOGGLE_VALUE>('NORMAL');

  const isHoverState = buttonStateToggleValue === BUTTON_HOVER_STATE_TOGGLE_VALUE;

  const button = nodeId
    ? adapter.tiptapEditor.view.dom.querySelector(`[data-hook~=button-viewer-${nodeId}`)
    : undefined;
  const buttonStyle = button ? window.getComputedStyle(button) : undefined;

  const styles = pmNodeAttrs?.styles;

  const textColor =
    styles?.textColor ??
    toHexFormatSafe(buttonStyle?.getPropertyValue('color')) ??
    defaultTextColor;
  const borderColor =
    styles?.borderColor ?? toHexFormatSafe(buttonStyle?.getPropertyValue('border-color'));
  const backgroundColor =
    (styles?.background?.type === 'COLOR' ? styles.background.color : undefined) ??
    styles?.backgroundColor ??
    defaultBackgroundColor ??
    toHexFormatSafe(buttonStyle?.getPropertyValue('background-color'));
  const borderWidth =
    styles?.borderWidth ??
    parseToInt(buttonStyle?.getPropertyValue('border-width')) ??
    defaultBorderWidth;
  const borderRadius =
    styles?.borderRadius ??
    parseToInt(buttonStyle?.getPropertyValue('border-radius')) ??
    defaultBorderRadius;
  const buttonSize =
    styles?.buttonSize ??
    themeButtonSizeMap[
      theme?.customStyles?.button?.buttonSize as keyof typeof themeButtonSizeMap
    ] ??
    ButtonData_Styles_ButtonSize.MEDIUM;
  const textColorHover =
    styles?.textColorHover ?? toHexFormatSafe(buttonStyle?.getPropertyValue('color')) ?? textColor;
  const borderColorHover =
    styles?.borderColorHover ??
    toHexFormatSafe(buttonStyle?.getPropertyValue('border-color')) ??
    borderColor;
  const backgroundColorHover =
    (styles?.backgroundHover?.type === 'COLOR' ? styles.backgroundHover.color : undefined) ??
    styles?.backgroundColorHover ??
    toHexFormatSafe(buttonStyle?.getPropertyValue('background-color')) ??
    backgroundColor;

  const backgroundGradient =
    styles?.background?.type === 'GRADIENT'
      ? schemaGradientToCss(styles.background.gradient, theme.colorPalette)
      : undefined;
  const backgroundGradientHover =
    styles?.backgroundHover?.type === 'GRADIENT'
      ? schemaGradientToCss(styles.backgroundHover.gradient, theme.colorPalette)
      : undefined;

  const setHoverPreview = (applyPreview: boolean) => {
    adapter.tiptapEditor.chain().setHoverPreview(applyPreview).run();
    forceUpdate();
  };

  useEffect(() => {
    setHoverPreview(isHoverState);

    return () => setHoverPreview(false);
  }, [isHoverState]);

  const handleOnChange = (
    newData: Partial<(PmLinkButtonNode | PmActionButtonNode)['attrs']['styles']>
  ) => {
    const newStyles = {
      ...styles,
      ...newData,
    };

    onChange({
      styles: {
        ...newStyles,
        borderRadius:
          newStyles?.borderRadius === defaultBorderRadius ? undefined : newStyles?.borderRadius,
        borderWidth:
          newStyles?.borderWidth === defaultBorderWidth ? undefined : newStyles?.borderWidth,
      },
    });
  };

  const showLiveSiteHint = environment !== 'liveSite' && environment !== 'wixel';

  const getDefaultColor = (colorType: ButtonColorType): string | undefined => {
    if (colorType === 'backgroundColor') {
      return isHoverState ? backgroundColorHover : backgroundColor;
    }
    if (colorType === 'textColor') {
      return isHoverState ? textColorHover : textColor;
    }
    return isHoverState ? borderColorHover : borderColor;
  };

  const openColorPicker = (colorType: ButtonColorType) => {
    const referenceElement = getPickerToggleRef(colorType) ?? undefined;
    const modalId = buttonsModals.colorPicker;

    modalService.togglePluginPanel({
      id: modalId,
      Component: ButtonColorPicker,
      componentProps: {
        modalId,
        nodeId,
        nodeType,
        colorType,
        isHoverState,
        referenceElement,
        config,
        defaultColor: getDefaultColor(colorType),
        onValueSelected: onValueChange(colorType),
        onColorAdded: getLegacyOnColorAdded(colorType),
      },
      isMobile,
      positioning: {
        referenceElement,
        placement: 'left',
      },
      type: undefined,
      onClickOutside: {
        on: 'pointerup',
        handler: () => {},
      },
      focusReturnElement: referenceElement ?? undefined,
    });
  };

  const onValueChange =
    (colorType: ButtonColorType) =>
    (value: { color?: string; gradient?: Gradient } | undefined) => {
      const hoverSuffix = isHoverState ? 'Hover' : '';

      if (colorType === 'backgroundColor') {
        const background = value
          ? value.gradient
            ? { type: 'GRADIENT' as const, gradient: value.gradient }
            : value.color
              ? { type: 'COLOR' as const, color: value.color }
              : undefined
          : undefined;
        handleOnChange({
          [`background${hoverSuffix}`]: background,
        });
      } else {
        handleOnChange({ [`${colorType}${hoverSuffix}`]: value?.color });
      }
    };

  const onColorChange = (colorType: ButtonColorType) => (color: string | undefined) =>
    onValueChange(colorType)(color ? { color } : undefined);

  const getLegacyOnColorAdded = (colorType: ButtonColorType) => {
    if (colorType === 'backgroundColor') {
      return config.onBackgroundColorAdded;
    } else if (colorType === 'textColor') {
      return config.onTextColorAdded;
    } else {
      return config.onBorderColorAdded;
    }
  };

  const getPickerToggleRef = (colorType: ButtonColorType) => {
    if (colorType === 'backgroundColor') {
      return backgroundPickerToggleRef.current;
    } else if (colorType === 'textColor') {
      return textPickerToggleRef.current;
    } else {
      return borderPickerToggleRef.current;
    }
  };

  return (
    <Box
      direction="vertical"
      width="100%"
      padding="SP4"
      paddingTop="SP3"
      paddingBottom="SP3"
      gap="SP2"
    >
      <FormField inputWidth="100%">
        <SegmentedToggle
          defaultSelected={buttonStateToggleValue}
          size="small"
          onClick={(_, value) => setButtonStateToggleValue(value as BUTTON_STATE_TOGGLE_VALUE)}
        >
          <SegmentedToggle.Button value={BUTTON_NORMAL_STATE_TOGGLE_VALUE}>
            {t('ButtonModal_Design_Normal_State_Toggle')}
          </SegmentedToggle.Button>
          <SegmentedToggle.Button value={BUTTON_HOVER_STATE_TOGGLE_VALUE}>
            {t('ButtonModal_Design_Hover_State_Toggle')}
          </SegmentedToggle.Button>
        </SegmentedToggle>
      </FormField>
      {isHoverState ? null : (
        <Box paddingTop="SP1">
          <FormField
            label={t('ButtonModal_Button_Size')}
            labelSize="small"
            labelPlacement="left"
            labelWidth="1fr"
            labelAlignment="middle"
          >
            <Box direction="horizontal" gap="6px">
              <SizeOption
                selected={buttonSize === ButtonData_Styles_ButtonSize.SMALL}
                icon={<ButtonRoundedSmall size={12} />}
                onClick={() => handleOnChange({ buttonSize: ButtonData_Styles_ButtonSize.SMALL })}
              />
              <SizeOption
                selected={buttonSize === ButtonData_Styles_ButtonSize.MEDIUM}
                icon={<ButtonRoundedSmall size={18} />}
                onClick={() => handleOnChange({ buttonSize: ButtonData_Styles_ButtonSize.MEDIUM })}
              />
              <SizeOption
                selected={buttonSize === ButtonData_Styles_ButtonSize.LARGE}
                icon={<ButtonRoundedSmall size={24} />}
                onClick={() => handleOnChange({ buttonSize: ButtonData_Styles_ButtonSize.LARGE })}
              />
            </Box>
          </FormField>
        </Box>
      )}
      <Box direction="vertical" gap="SP3">
        <ColorWithOpacityInput
          label={t('ButtonModal_Background_Color')}
          fill={(() => {
            const gradient = isHoverState ? backgroundGradientHover : backgroundGradient;
            return gradient
              ? { type: 'gradient', gradient }
              : {
                  type: 'color',
                  color: isHoverState ? backgroundColorHover : backgroundColor,
                  onChange: onColorChange('backgroundColor'),
                };
          })()}
          onColorPress={() => openColorPicker('backgroundColor')}
          colorPickerRef={backgroundPickerToggleRef}
          inputDataHook={DESIGN_SETTINGS_BACKGROUND_COLOR_INPUT}
          zIndex={zIndex}
        />
        {showLiveSiteHint && <ColorPickerLiveSiteColorHint />}
      </Box>
      <FieldSet
        legend={t('ButtonModal_Text_Color')}
        legendPlacement="left"
        columns={'auto 30px'}
        alignment="center"
        dataHook={DESIGN_SETTINGS_TEXT_COLOR_INPUT}
      >
        <div />
        <FillPreview
          fill={resolveColorToDisplayHex(isHoverState ? textColorHover : textColor, containerEl)}
          onClick={() => openColorPicker('textColor')}
          ref={textPickerToggleRef}
          dataHook={SWATCH_TOGGLE}
        />
      </FieldSet>
      <ColorWithOpacityInput
        label={t('ButtonModal_Border_Color')}
        fill={{
          type: 'color',
          color: isHoverState ? borderColorHover : borderColor,
          onChange: onColorChange('borderColor'),
        }}
        onColorPress={() => openColorPicker('borderColor')}
        colorPickerRef={borderPickerToggleRef}
        inputDataHook={DESIGN_SETTINGS_BORDER_COLOR_INPUT}
        zIndex={zIndex}
      />
      {isHoverState ? null : (
        <NumberInputWithLabel
          label={t('ButtonModal_Width_Input')}
          dataHook={DESIGN_SETTINGS_BORDER_WIDTH_INPUT}
          suffix={<Input.Affix>{t('Common_Units_PX')}</Input.Affix>}
          value={borderWidth}
          min={0}
          max={15}
          onChange={width => handleOnChange({ borderWidth: width })}
          logBi={logBi}
          zIndex={zIndex}
        />
      )}
      {isHoverState ? null : (
        <NumberInputWithLabel
          label={t('ButtonModal_Radius_Input')}
          dataHook={DESIGN_SETTINGS_CORNER_RADIUS_INPUT}
          suffix={<Input.Affix>{t('Common_Units_PX')}</Input.Affix>}
          value={borderRadius}
          min={0}
          max={30}
          onChange={radius => handleOnChange({ borderRadius: radius })}
          logBi={logBi}
          zIndex={zIndex}
        />
      )}
    </Box>
  );
};

const SizeOption: React.FC<{ icon: ReactNode; selected: boolean; onClick: () => void }> = ({
  icon,
  selected,
  onClick,
}) => {
  return (
    <Thumbnail
      height={30}
      width={30}
      size="tiny"
      onClick={onClick}
      selected={selected}
      noPadding
      contentAlignment={'center'}
    >
      <Box align="center">{icon}</Box>
    </Thumbnail>
  );
};

const toHexFormatSafe = (color?: string) => {
  return color ? toHexFormat(color) : undefined;
};

const parseToInt = (value: string | undefined): number | undefined => {
  if (value === undefined) {
    return undefined;
  }

  const parsedValue = parseInt(value);
  return isNaN(parsedValue) ? undefined : parsedValue;
};
