import type { ButtonViewer } from './viewer/button-viewer.js';

export const LINK_BUTTON_TYPE = 'wix-draft-plugin-link-button';
export const ACTION_BUTTON_TYPE = 'wix-draft-plugin-action-button';

export type LinkButtonPluginEditorConfig = { type: 'linkButton' } & ButtonPluginEditorConfigCommon;
export interface LinkButtonPluginViewerConfig extends ButtonPluginViewerConfigCommon {}

export type ActionButtonPluginEditorConfig = {
  type: 'actionButton';
} & ButtonPluginEditorConfigCommon;
export interface ActionButtonPluginViewerConfig extends ButtonPluginViewerConfigCommon {}

export type ButtonCommonEditorConfig =
  | LinkButtonPluginEditorConfig
  | ActionButtonPluginEditorConfig;

interface ButtonPluginViewerConfigCommon {
  colors?: {
    color1?: string; // used for default textColor
    color2?: string;
    color3?: string;
    color4?: string;
    color5?: string;
    color6?: string;
    color7?: string;
    color8?: string; // used for default border and background color
    color9?: string;
    color10?: string;
  };
}

export interface ButtonPluginEditorConfigCommon {
  colors?: {
    color1?: string; // used for default textColor
    color2?: string;
    color3?: string;
    color4?: string;
    color5?: string;
    color6?: string;
    color7?: string;
    color8?: string; // used for default border and background color
    color9?: string;
    color10?: string;
  };
  /** @deprecated Use colorManager prop instead */
  onTextColorAdded?: (color: string) => string[];
  /** @deprecated Use colorManager prop instead */
  onBackgroundColorAdded?: (color: string) => string[];
  /** @deprecated Use colorManager prop instead */
  onBorderColorAdded?: (color: string) => string[];
  /** @deprecated Use colorManager prop instead */
  getTextColors?: () => string[];
  /** @deprecated Use colorManager prop instead */
  getBorderColors?: () => string[];
  /** @deprecated Use colorManager prop instead */
  getBackgroundColors?: () => string[];
  customComponent?: (props: React.ComponentProps<typeof ButtonViewer>) => JSX.Element;
  disableResize?: boolean;
}
