import { Box, Tabs } from '@wix/design-system';
import React, { useContext, useMemo } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import { ACTION_COLOR_DEFAULT } from './../../ricos-styles/theme-constants.js';
import type { LogBiFn } from './../../_shared/bi-context-provider/bi-context-provider.js';
import type { PmActionButtonNode, PmLinkButtonNode, PmNodeType } from './../../_shared/pm-node-types.js';
import { unreachable } from './../../_shared/uncreachable.js';
import { dataHook } from './../../wix-rich-content-common/index.js';
import { Panel, PanelHeader } from './../../ui-components/index.js';

import { DesignComponent } from '../components/design-component.js';
import { SettingsComponent } from '../components/settings-component.js';
import type { SettingsTab } from '../constants.js';
import { SETTINGS_TAB } from '../constants.js';
import {
  ROOT,
  SETTINGS_DESIGN_TAB,
  SETTINGS_GENERAL_TAB,
  SETTINGS_MODAL,
  SETTINGS_TABS,
} from '../data-hooks.js';
import classes from '../statics/styles/button-input-modal-scss.js';
import type { ButtonPluginEditorConfigCommon } from '../types.js';

type Props = {
  buttonData: (PmLinkButtonNode | PmActionButtonNode)['attrs'];
  config: ButtonPluginEditorConfigCommon;
  onClose: () => void;
  onChange: (data: Partial<(PmLinkButtonNode | PmActionButtonNode)['attrs']>) => void;
  nodeId: string;
  nodeType: typeof PmNodeType.LINK_BUTTON | typeof PmNodeType.ACTION_BUTTON;
  activeTab: SettingsTab;
  onTabChange: (tab: SettingsTab) => void;
  logBi: LogBiFn;
};

export const SettingsModalContent: React.FC<Props> = ({
  buttonData,
  onChange,
  config,
  nodeId,
  nodeType,
  activeTab,
  onTabChange,
  onClose,
  logBi,
}) => {
  const { t, isMobile } = useContext(RicosContext);

  const { defaultBackgroundColor, defaultTextColor } = useMemo(() => {
    const button = document.querySelector(dataHook(`editor-${nodeId}`, ROOT));
    const style = button ? window.getComputedStyle(button) : undefined;
    // var name and fallback taken from statics/styles/default-styles.scss
    const defaultBackgroundColor =
      config.colors?.color8 ??
      (style?.getPropertyValue('--ricos-action-color') || ACTION_COLOR_DEFAULT);
    const defaultTextColor =
      config.colors?.color1 ??
      (style?.getPropertyValue('--ricos-text-on-action-color') ||
        style?.getPropertyValue('--ricos-background-color') ||
        '#FFFFFF');
    return { defaultBackgroundColor, defaultTextColor };
  }, []);

  return (
    <div className={classes.modal}>
      <Panel closeButtonProps={{ onClick: onClose }} dataHook={SETTINGS_MODAL}>
        <PanelHeader title={t('ButtonModal_Header')} />
        <Tabs
          dataHook={SETTINGS_TABS}
          onClick={tab => onTabChange(tab.id as SettingsTab)}
          activeId={activeTab}
          size="small"
          alignment="center"
          type="uniformFull"
          minWidth={0}
          items={[
            {
              id: SETTINGS_TAB.SETTINGS,
              title: t('ButtonModal_Settings_Tab'),
              dataHook: SETTINGS_GENERAL_TAB,
            },
            {
              id: SETTINGS_TAB.DESIGN,
              title: t('ButtonModal_Design_Tab'),
              dataHook: SETTINGS_DESIGN_TAB,
            },
          ]}
        />
        <Box className={isMobile ? undefined : classes.content}>
          {(() => {
            switch (activeTab) {
              case SETTINGS_TAB.SETTINGS:
                return (
                  <SettingsComponent buttonData={buttonData} onChange={onChange} logBi={logBi} />
                );
              case SETTINGS_TAB.DESIGN:
                return (
                  <DesignComponent
                    onChange={onChange}
                    config={config}
                    defaultBackgroundColor={defaultBackgroundColor}
                    defaultTextColor={defaultTextColor}
                    nodeId={nodeId}
                    nodeType={nodeType}
                    logBi={logBi}
                  />
                );
              default:
                unreachable(activeTab);
                return null;
            }
          })()}
        </Box>
      </Panel>
    </div>
  );
};
