import { ButtonPill } from '@wix/wix-ui-icons-common/lazy';

import buttonDataDefaults from './../ricos-schema/legacy/statics/button.defaults.json.js';
import type { AddButton, RicosServices } from './../ricos-types/index.js';
import { Node_Type } from './../ricos-types/index.js';
import { getInitialLinkData } from './../_shared/link/get-initial-link-data.js';
import { INSERT_PLUGIN_BUTTONS, TOOLBARS } from './../editor-common/index.js';
import type {
  ACTION_BUTTON_TYPE,
  ButtonCommonEditorConfig,
  LINK_BUTTON_TYPE,
} from './/types.js';

import { BUTTONS_TYPE_TO_TIPTAP_ATTR } from './constants.js';
import { INSERT_BUTTON_BUTTON } from './data-hooks.js';

export const toolbarsToAddIn: (TOOLBARS.MOBILE | TOOLBARS.FOOTER | TOOLBARS.SIDE)[] = [
  TOOLBARS.FOOTER,
  TOOLBARS.SIDE,
  TOOLBARS.MOBILE,
];

export const getAddButtons = (
  config: ButtonCommonEditorConfig,
  _services: RicosServices,
  type: typeof LINK_BUTTON_TYPE | typeof ACTION_BUTTON_TYPE
): AddButton[] => {
  return [
    {
      id: Node_Type.BUTTON,
      label: INSERT_PLUGIN_BUTTONS.BUTTON,
      dataHook: INSERT_BUTTON_BUTTON,
      icon: ButtonPill,
      // @ts-ignore TODO: (plugins-no-any) remove insertButtonTooltip when we make sure it's not used anymore
      tooltip: config?.insertButtonTooltip || 'ButtonPlugin_InsertButton_Tooltip',
      toolbars: toolbarsToAddIn,
      command: ({ publicCommands }) => {
        const initialLinkOptions = getInitialLinkData(
          _services.editorProps.generalLinkSettings?.initialLinkOptions
        );
        publicCommands.insertBlockWithBlankLines(type, {
          ...(buttonDataDefaults as $TSFixMe),
          link: initialLinkOptions,
          type: BUTTONS_TYPE_TO_TIPTAP_ATTR[type],
        });
        return true;
      },
      menuConfig: {
        tags: 'Button_plugin_search_tags',
        group: 'advanced',
      },
    },
  ];
};
