import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import { ModalServiceContext } from './../../ricos-context/modal-context.js';
import type { Gradient } from './../../ricos-types/color-palette-types.js';
import { useBiNext } from './../../_shared/bi-context-provider/bi-context-provider.js';
import {
  handleColorAdded,
  handleColorDeleted,
  handleGradientAdded,
  handleGradientDeleted,
  resolveThemeColorsPalette,
  useResolvedCustomColors,
  useResolvedCustomGradients,
} from './../../_shared/color-manager-utils.js';
import { type PmNodeType } from './../../_shared/pm-node-types.js';
import { useNodeAttrs } from './../../_shared/use-node-attrs.js';
import { NewColorPicker } from './../../ui-components/color-picker/new-color-picker/index.js';

import type { ButtonPluginEditorConfigCommon } from '../types.js';
import type { ButtonColorType } from './design-component.js';

type ButtonColorPickerProps = {
  modalId: string;
  nodeId: string;
  nodeType: typeof PmNodeType.LINK_BUTTON | typeof PmNodeType.ACTION_BUTTON;
  colorType: ButtonColorType;
  isHoverState: boolean;
  referenceElement: HTMLDivElement | undefined;
  config: ButtonPluginEditorConfigCommon;
  defaultColor?: string;
  onValueSelected: (value: { color?: string; gradient?: Gradient } | undefined) => void;
  onColorAdded?: (color: string) => void;
};

export const ButtonColorPicker: React.FC<ButtonColorPickerProps> = ({
  modalId,
  nodeId,
  nodeType,
  colorType,
  isHoverState,
  referenceElement,
  config,
  defaultColor,
  onValueSelected,
  onColorAdded: onColorAddedProp,
}) => {
  const modalService = useContext(ModalServiceContext);
  const { t, colorManager, theme } = useContext(RicosContext);

  const { pmNodeAttrs } = useNodeAttrs(nodeId, nodeType);

  const logBi = useBiNext({
    modalId,
    pluginId: nodeType === 'LINK_BUTTON' ? 'linkButton' : 'actionButton',
    nodeId,
  });

  const themeColors = resolveThemeColorsPalette(
    theme,
    config.colors ? Object.values(config.colors) : []
  );

  const legacyColorCallback =
    colorType === 'textColor'
      ? config.getTextColors
      : colorType === 'borderColor'
        ? config.getBorderColors
        : config.getBackgroundColors;

  const customColors = useResolvedCustomColors(colorManager, legacyColorCallback);
  const customGradients = useResolvedCustomGradients(colorManager);

  const onColorAdded = (color: string) => {
    handleColorAdded(color, colorManager, onColorAddedProp);
    onValueSelected({ color });
  };

  const onGradientAdded = (gradient: Gradient) => {
    handleGradientAdded(gradient, colorManager);
    onValueSelected({ gradient });
  };

  const onGradientDeleted = (gradient: Gradient) => {
    handleGradientDeleted(gradient, colorManager);
  };

  const onColorDeleted = (color: string) => {
    handleColorDeleted(color, colorManager);
  };

  const currentBackground = isHoverState
    ? pmNodeAttrs?.styles?.backgroundHover
    : pmNodeAttrs?.styles?.background;

  const legacyBackgroundColor = isHoverState
    ? pmNodeAttrs?.styles?.backgroundColorHover
    : pmNodeAttrs?.styles?.backgroundColor;

  const currentColor = (() => {
    if (colorType === 'backgroundColor') {
      const color =
        currentBackground?.type === 'COLOR' ? currentBackground.color : legacyBackgroundColor;
      return color?.toUpperCase();
    }
    if (colorType === 'textColor') {
      return (
        isHoverState ? pmNodeAttrs?.styles?.textColorHover : pmNodeAttrs?.styles?.textColor
      )?.toUpperCase();
    }
    return (
      isHoverState ? pmNodeAttrs?.styles?.borderColorHover : pmNodeAttrs?.styles?.borderColor
    )?.toUpperCase();
  })();

  const currentGradient =
    colorType === 'backgroundColor' && currentBackground?.type === 'GRADIENT'
      ? currentBackground.gradient
      : undefined;

  const allowGradient = colorType === 'backgroundColor';

  return (
    <NewColorPicker
      themeColors={themeColors}
      customColors={customColors}
      customGradients={allowGradient ? customGradients : undefined}
      currentColor={currentGradient ?? currentColor ?? defaultColor?.toUpperCase()}
      fallbackColor={currentColor ?? defaultColor?.toUpperCase()}
      title={t('ButtonColourModal_Title')}
      closeModal={() => modalService.closeModal(modalId)}
      onColorSelected={color => onValueSelected(color ? { color } : undefined)}
      onGradientSelected={gradient => onValueSelected({ gradient })}
      onColorAdded={onColorAdded}
      onColorDeleted={colorManager || !legacyColorCallback ? onColorDeleted : undefined}
      onResetColor={() => onValueSelected(undefined)}
      onGradientAdded={allowGradient ? onGradientAdded : undefined}
      onGradientDeleted={allowGradient ? onGradientDeleted : undefined}
      referenceElement={referenceElement}
      logBi={logBi}
      allowGradient={allowGradient}
      allowTransparent={colorType !== 'textColor'}
    />
  );
};
